import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import axios from 'axios';
import UserDetailsForm from './components/UserDetailsForm';
import ChatInterface from './components/ChatInterface';
import ResumePreview from './components/ResumePreview';

function App() {
  const [sessionId, setSessionId] = useState('');
  const [userDetails, setUserDetails] = useState({
    name: '',
    title: '',
    phone: '',
    email: '',
    location: ''
  });
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [resumeData, setResumeData] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    startNewSession();
  }, []);

  const startNewSession = async () => {
    try {
      const response = await axios.post('http://localhost:8000/api/session');
      setSessionId(response.data.session_id);
    } catch (error) {
      console.error('Error starting session:', error);
    }
  };

  const handleUserDetailsSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post(`http://localhost:8000/api/details?session_id=${sessionId}`, userDetails);
      addMessage('Bot', 'Great! I have your details. Let\'s start building your resume. What would you like to focus on first?');
    } catch (error) {
      console.error('Error submitting details:', error);
    }
  };

  const handleSendMessage = async (e) => {
    e.preventDefault();
    if (!inputMessage.trim()) return;

    const userMessage = inputMessage;
    setInputMessage('');
    addMessage('You', userMessage);
    setLoading(true);

    try {
      const response = await axios.post(`http://localhost:8000/api/generate?session_id=${sessionId}`);
      setResumeData(response.data);
      addMessage('Bot', 'I\'ve generated your resume! You can preview it below and download it as a DOCX file.');
    } catch (error) {
      console.error('Error generating resume:', error);
      addMessage('Bot', 'Sorry, there was an error generating your resume. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const addMessage = (sender, text) => {
    setMessages(prev => [...prev, { sender, text, timestamp: new Date().toLocaleTimeString() }]);
  };

  const handleDownload = async () => {
    try {
      const response = await axios.get(`http://localhost:8000/api/download?session_id=${sessionId}`, {
        responseType: 'blob'
      });
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `resume_${sessionId}.docx`);
      document.body.appendChild(link);
      link.click();
      link.remove();
    } catch (error) {
      console.error('Error downloading resume:', error);
    }
  };

  return (
    <Router>
      <div className="min-h-screen bg-gray-100">
        <div className="container mx-auto px-4 py-8">
          <h1 className="text-4xl font-bold text-center mb-8">ResuLLMe</h1>
          
          <Routes>
            <Route
              path="/"
              element={
                !resumeData ? (
                  <UserDetailsForm
                    userDetails={userDetails}
                    setUserDetails={setUserDetails}
                    onSubmit={handleUserDetailsSubmit}
                  />
                ) : (
                  <Navigate to="/chat" replace />
                )
              }
            />
            <Route
              path="/chat"
              element={
                <div className="space-y-8">
                  <ChatInterface
                    messages={messages}
                    inputMessage={inputMessage}
                    setInputMessage={setInputMessage}
                    onSendMessage={handleSendMessage}
                    loading={loading}
                  />
                  <ResumePreview
                    resumeData={resumeData}
                    onDownload={handleDownload}
                  />
                </div>
              }
            />
          </Routes>
        </div>
      </div>
    </Router>
  );
}

export default App;
